import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { cuisineQuest } from "../src/cuisine-quest";
import { goldenCase, playBot, type BotProfile } from "./helpers/quest-bot";

/**
 * Pins campaign behaviour. The fixture was generated by the engine as it stood
 * on main at 2aeab76, before any refactoring, so a saved score, star or replay
 * can't silently change. Run with CQ_GOLDEN_WRITE=1 only for an intentional
 * rules change, and treat that as a migration of player-visible results.
 */
const FIXTURE = new URL("./fixtures/cuisine-quest-golden.json", import.meta.url);
const LEVELS = [1, 2, 3, 4, 5, 6, 7];
const SEEDS = [1, 17, 123, 987654];
const PROFILES: BotProfile[] = ["clean", "human", "messy"];
const cases = LEVELS.flatMap((level) => SEEDS.flatMap((seed) => PROFILES.map((profile) => ({ level, seed, profile }))));

if (process.env.CQ_GOLDEN_WRITE === "1") {
  writeFileSync(FIXTURE, `${JSON.stringify(cases.map((c) => goldenCase(c.level, c.seed, c.profile)), null, 1)}\n`);
}

describe("Cuisine Quest campaign golden replays", () => {
  const golden: ReturnType<typeof goldenCase>[] = existsSync(FIXTURE) ? JSON.parse(readFileSync(FIXTURE, "utf8")) : [];
  it("covers every kitchen, seed and play style", () => expect(golden).toHaveLength(84));
  it("exercises wins, partial services and real failures", () => {
    expect(new Set(golden.map((g) => g.details.stars))).toEqual(new Set([0, 1, 2, 3]));
    expect(golden.some((g) => Number(g.details.burnt) > 0)).toBe(true);
    expect(golden.some((g) => Number(g.details.missed) > 0)).toBe(true);
    expect(golden.some((g) => g.rejected > 0)).toBe(true);
  });
  it.each(cases)("level $level seed $seed $profile is unchanged", ({ level, seed, profile }) => {
    const pinned = golden.find((g) => g.level === level && g.seed === seed && g.profile === profile)!;
    const { details: pinnedDetails, ...pinnedRest } = pinned;
    const { details, ...rest } = goldenCase(level, seed, profile);
    expect(rest).toEqual(pinnedRest);
    // New detail keys are additive; every value a saved run was built from must match.
    expect(details).toMatchObject(pinnedDetails);
  });
  it.each(PROFILES)("the server verifier accepts a %s log and reaches the same result", (profile) => {
    const { log, result } = playBot(3, 17, profile);
    expect(cuisineQuest.verify(17, { level: 3 }, log)).toEqual({ ok: true, result });
  });
});
